<section class="client-panel"><div class="client-section-heading"><div><h2>Personal Profile</h2><p>These values are reused in the demonstration verification workflow.</p></div></div><form method="post" action="<?=e(site_url('api/verification/profile'))?>" class="kyc-form-grid" data-kyc-ajax><?=csrf_field()?><?php foreach($fields as $key=>$label): ?><label class="kyc-field<?=in_array($key,['address_line_1','address_line_2'],true)?' is-wide':''?>"><?=e($label)?><?php if(in_array($key,['country','nationality'],true)): ?><select name="<?=e($key)?>" <?=($locked?'disabled':'')?>><option value="">Choose country</option><?php foreach($countryOptions as $code=>$name): ?><option value="<?=e($code)?>" <?=strtoupper((string)($profile[$key]??''))===$code?'selected':''?>><?=e($name)?></option><?php endforeach; ?></select><?php else: ?><input name="<?=e($key)?>" type="<?=$key==='date_of_birth'?'date':'text'?>" value="<?=e($profile[$key]??'')?>" <?=in_array($key,['first_name','last_name','phone','date_of_birth','country','nationality','address_line_1','city'],true)?'required':''?> <?=($locked?'readonly':'')?>><?php endif; ?></label><?php endforeach; ?><div class="kyc-form-actions is-wide"><button class="client-button client-button-primary" type="submit" <?=($locked?'disabled':'')?>>Save Profile</button><span data-kyc-message role="status"></span></div></form></section><section class="client-panel"><div class="client-section-heading"><div><h2>Account Security</h2><p>Email and password use dedicated secure flows.</p></div></div><a class="client-text-link" href="<?=e(site_url('forgot-password'))?>">Reset password →</a></section>
